contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes32 _txid) public {
        bool approved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool r = c.logRedeemed(_txid); if (__ESBMC_reverted()) return;
        assert(!approved && !r && !c.approvedToLog(address(this)));
    }
    receive() external payable {}
}

