pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bytes32 _txid) internal {
        bool approved;
        try c.approvedToLog(address(this)) returns (bool __r) { approved = __r; } catch { return; }
        bool r;
        try c.logRedeemed(_txid) returns (bool __r) { r = __r; } catch { return; }
        assertTrue(!approved && !r && !c.approvedToLog(address(this)));
    }

    function testFuzz_run(bytes32 _txid) public {
        _run(_txid);
    }

    receive() external payable {}
}
